+/** Native observations for the existing pure artifact-release comparison.
+ * Reading an archive neither extracts it nor claims native installation.
+ */
+import { constants } from 'node:fs';
+import { open, lstat, readFile, readdir, realpath, mkdtemp, writeFile, rm } from 'node:fs/promises';
+import { createHash } from 'node:crypto';
+import { isAbsolute, join, relative } from 'node:path';
+import { execFile } from 'node:child_process';
+import { promisify } from 'node:util';
+import { setImmediate as turn } from 'node:timers/promises';
+import { gunzipSync } from 'node:zlib';
+import { Parser } from 'tar';
+import { admitArtifactRelease } from './artifact-release.mjs';
+import { carrierSourceIncludes } from './carrier-surface.mjs';
+import { npmPackResult } from './npm-pack-result.mjs';
+import { preparePublicationCarrierManifest } from './publication-carrier-manifest.mjs';
+import { receiveQualifiedPublicationBuildProducts } from './source-build-qualification.mjs';
+const run = promisify(execFile);
+
+const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
+const decode = bytes => new TextDecoder('utf-8', { fatal: true }).decode(bytes);
+const fail = (message, code = 'artifact-member-receiving-refused') => Object.assign(new TypeError(message), { code });
+function fields(value, names, label) {
+  if (!value || typeof value !== 'object' || Array.isArray(value) || Object.keys(value).some(key => !names.includes(key)))
+    throw fail(label + ' requires its exact native receiving fields');
+}
+function bounds(value) {
+  const ceilings = { members: 100000, bytes: 256 * 1024 * 1024, archiveBytes: 64 * 1024 * 1024,
+    tarBytes: 256 * 1024 * 1024, metadataBytes: 1024 * 1024, sourcePaths: 1000000, sourceRepositories: 4096 };
+  fields(value, Object.keys(ceilings), 'limits');
+  for (const [name, ceiling] of Object.entries(ceilings)) if (!Number.isSafeInteger(value[name]) || value[name] < 1 || value[name] > ceiling)
+    throw fail('finite native receiving bound required: ' + name);
+  return value;
+}
+function literal(path) {
+  return typeof path === 'string' && path.length > 0 && !path.startsWith('/') && !/[\\\x00-\x1f\x7f]/u.test(path)
+    && !path.split('/').some(part => !part || part === '.' || part === '..');
+}
+function unambiguous(path) {
+  if (typeof path !== 'string' || path.includes('\ufffd')) throw fail('archive name encoding is not losslessly received', 'unread-archive-name-encoding');
+}
+function memberPath(path, directory) {
+  unambiguous(path);
+  if (!path.startsWith('package/')) throw fail('archive member is outside the single npm package container');
+  const local = path.slice('package/'.length);
+  if (directory && local === '') return '';
+  const selected = directory && local.endsWith('/') ? local.slice(0, -1) : local;
+  if (!literal(selected)) throw fail('unsafe or aliased archive member path');
+  return selected;
+}
+const member = (path, bytes, mode) => ({ path, kind: 'file', bytes: bytes.length, sha256: sha256(bytes), mode });
+const statIdentity = value => [value.dev, value.ino, value.size, value.mtimeNs, value.ctimeNs].map(String);
+
+/** The maintained parser owns TAR framing and interpretation. The original
+ * archive and expanded digest retain all bytes, including headers and padding.
+ * Its public eof event, not another TAR codec, determines trailing padding.
+ */
+export async function readRegistryArchiveMembers({ path, integrity, limits }) {
+  bounds(limits);
+  if (typeof path !== 'string' || !isAbsolute(path)) throw fail('exact absolute archive path required');
+  if (typeof integrity !== 'string' || !/^sha512-[A-Za-z0-9+/]{86}==$/u.test(integrity)
+    || Buffer.from(integrity.slice(7), 'base64').length !== 64
+    || Buffer.from(integrity.slice(7), 'base64').toString('base64') !== integrity.slice(7)) throw fail('canonical SHA512 archive identity required');
+  const namedBefore = await lstat(path, { bigint: true });
+  if (!namedBefore.isFile()) throw fail('archive pathname must name a regular file directly');
+  const file = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
+  let bytes, before;
+  try {
+    before = await file.stat({ bigint: true });
+    if (JSON.stringify(statIdentity(before)) !== JSON.stringify(statIdentity(namedBefore))) throw fail('archive pathname changed before opening');
+    if (!before.isFile() || before.size > BigInt(limits.archiveBytes)) throw fail('archive must be a bounded regular file');
+    const buffer = Buffer.alloc(limits.archiveBytes + 1);
+    let length = 0;
+    while (length < buffer.length) {
+      const next = await file.read(buffer, length, buffer.length - length, null);
+      if (!next.bytesRead) break;
+      length += next.bytesRead;
+    }
+    if (length > limits.archiveBytes) throw fail('archive exceeded its bound during reading');
+    bytes = buffer.subarray(0, length);
+    if (JSON.stringify(statIdentity(await file.stat({ bigint: true }))) !== JSON.stringify(statIdentity(before))) throw fail('archive changed while reading');
+    const namedAfter = await lstat(path, { bigint: true });
+    if (!namedAfter.isFile() || JSON.stringify(statIdentity(namedAfter)) !== JSON.stringify(statIdentity(before))) throw fail('archive pathname changed while reading');
+  } finally { await file.close(); }
+  if ('sha512-' + createHash('sha512').update(bytes).digest('base64') !== integrity) throw fail('archive differs from its received SHA512 identity');
+  // Native bounded decompression precedes parsing; ignored/empty metadata cannot
+  // turn compressed size or payload-only accounting into an expansion allowance.
+  const tar = gunzipSync(bytes, { maxOutputLength: limits.tarBytes });
+  if (!tar.length || tar.length % 512 !== 0) throw fail('archive is not complete TAR blocks');
+  const parser = new Parser({ strict: true, maxMetaEntrySize: limits.metadataBytes });
+  const members = [], headers = [], names = new Map(), implicitParents = new Set();
+  let failure, eof = false, eofOffset = null, payloadBytes = 0, manifestText;
+  const refuse = error => { failure ??= error instanceof Error ? error : fail(String(error)); };
+  parser.on('error', refuse);
+  parser.on('warn', () => refuse(fail('archive parser reported an uninterpreted or invalid archive')));
+  parser.on('ignoredEntry', () => refuse(fail('archive contains an ignored or unsupported member')));
+  // This first native context does not guess at PAX/GNU encoding or override
+  // interpretation. Such inputs remain unread until a lossless maintained port
+  // is qualified; the pure model's other supplied-fact interfaces stay intact.
+  parser.on('meta', () => refuse(fail('archive extension interpretation is not received', 'unread-archive-extension')));
+  parser.on('eof', () => { eof = true; });
+  parser.on('entry', entry => {
+    try {
+      if (headers.length >= limits.members) throw fail('archive header/member bound exceeded');
+      const directory = entry.type === 'Directory';
+      if (!directory && !['File', 'OldFile'].includes(entry.type)) throw fail('archive requires regular files, not links or special members');
+      if (!Number.isSafeInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777
+        || !Number.isSafeInteger(entry.size) || entry.size < 0 || directory && entry.size !== 0) throw fail('archive member mode or size is invalid');
+      if (entry.path !== entry.header.path) throw fail('archive parser normalized an unreceived name');
+      const path = memberPath(entry.path, directory);
+      if (names.has(path)) throw fail('duplicate or aliased archive member');
+      for (let slash = path.indexOf('/'); slash >= 0; slash = path.indexOf('/', slash + 1)) {
+        const parent = path.slice(0, slash);
+        if (names.get(parent) === 'file') throw fail('archive file is also a parent directory');
+        implicitParents.add(parent);
+      }
+      if (!directory && implicitParents.has(path)) throw fail('archive file replaces a member directory');
+      names.set(path, directory ? 'directory' : 'file');
+      headers.push({ path: entry.path, type: entry.type, mode: entry.mode, size: entry.size });
+      if (directory) { entry.resume(); return; }
+      payloadBytes += entry.size;
+      if (!Number.isSafeInteger(payloadBytes) || payloadBytes > limits.bytes) throw fail('expanded member payload bound exceeded');
+      const hash = createHash('sha256'), manifest = [];
+      let length = 0;
+      entry.on('data', chunk => {
+        length += chunk.length; hash.update(chunk);
+        if (length > entry.size) refuse(fail('archive member body exceeded its header'));
+        if (path === 'package.json') manifest.push(chunk);
+      });
+      entry.on('end', () => {
+        if (length !== entry.size) { refuse(fail('archive member body differs from its header')); return; }
+        members.push({ path, kind: 'file', bytes: length, sha256: hash.digest('hex'), mode: entry.mode });
+        if (path === 'package.json') { try { manifestText = decode(Buffer.concat(manifest)); } catch (error) { refuse(error); } }
+      });
+    } catch (error) { refuse(error); }
+    entry.resume();
+  });
+  const finished = new Promise(resolve => parser.once('end', resolve));
+  // Feed bounded blocks and allow the parser's public events to settle. No TAR
+  // header, body-length or extension decoding is duplicated here.
+  for (let offset = 0; offset < tar.length; offset += 512) {
+    parser.write(tar.subarray(offset, offset + 512));
+    await turn();
+    if (failure) throw failure;
+    if (eof) {
+      eofOffset = offset + 512;
+      if (!tar.subarray(eofOffset).every(byte => byte === 0)) throw fail('archive has nonzero data after the parser end marker');
+      break;
+    }
+  }
+  parser.end(); await finished;
+  if (failure) throw failure;
+  if (!eof || manifestText === undefined) throw fail('archive end marker and exact package manifest are required');
+  const accountedEndOffset = headers.reduce((sum, header) => sum + 512 + Math.ceil(header.size / 512) * 512, 1024);
+  if (accountedEndOffset !== eofOffset) throw fail('native parser header accounting is incomplete', 'unread-archive-header-accounting');
+  return { archive: { integrity, manifestText, members }, observation: {
+    kind: 'npm.native-archive-members', path, integrity, archiveSHA256: sha256(bytes), compressedBytes: bytes.length,
+    expandedSHA256: sha256(tar), expandedBytes: tar.length, parserEndOffset: eofOffset, accountedEndOffset, headers,
+    parser: { name: 'tar', context: 'regular-npm-gzip-tar', extensions: 'unreceived', ambiguousNames: 'unreceived' },
+    extracted: false, installationClaimed: false,
+  } };
+}
+
+/** Native NPM owns its packlist and ignore/config precedence. No lifecycle,
+ * inherited credentials or user/global npm config enters this bounded observer.
+ */
+async function nativePackSelection(directory, manifest, scratchDirectory) {
+  const scratch = await mkdtemp(join(scratchDirectory, 'code-native-packlist-'));
